def register_storage(add,C,R,O):
    from storage_fixtures import fixtures,query_data
    fixtures=fixtures()
    nodes=[dict(path='data',kind='dir'),dict(path='data/a.txt',kind='file',content='A'),dict(path='inside.txt',kind='symlink',target='data/a.txt'),dict(path='shortcut',kind='symlink',target='data'),dict(path='external.txt',kind='symlink',target='../outside.txt')]
    add('N15','symlink_preserving_archive',[
        C('member_plan','archive_plan',{'nodes':R+'/nodes','external_files':R+'/external_files'},"输入为受控虚拟 collection 根目录，nodes=[{path,kind:'file'|'dir'|'symlink',content或target}]，symlink相对所在目录解析。没有循环/悬空链接；外部文件内容由external_files以绝对虚拟路径给出，不读实际工作区外文件。规范化后落在/collection外的成员路径拒绝；内部链接保留为symlink，其相对linkname不展开；外部文件链接复制内容为普通file。返回 {members:按name排序[{name,type,content(仅file),linkname(仅symlink)}],rejected:排序拒绝path}。目录没有多余字段。"),
        C('archive','build_archive',{'plan':O('member_plan')},"用tarfile生成真实tar，返回 {tar:base64字节,rejected:计划中的拒绝路径}。成员语义必须与plan一致；允许任何合法tar编码，不按压缩字节逐字匹配。",emit={'outputs/collection.tar':{'pointer':'/tar','format':'base64'}}),
        C('archive_report','inspect_archive',{'archive':O('archive')},"实际读取tar成员，不展开符号链接目录。返回 {members:与member_plan同格式且按name排序,rejected:输入rejected}。内部文件/目录链接均保留，不能把目录链接子项复制进去。")],
        [dict(nodes=nodes,external_files={'/outside.txt':'EXT'}),dict(nodes=[dict(path='a.txt',kind='file',content='hello'),dict(path='../escape.txt',kind='file',content='BLOCK'),dict(path='b',kind='symlink',target='a.txt')],external_files={}),dict(nodes=[dict(path='d',kind='dir'),dict(path='d/x',kind='file',content='X'),dict(path='d/y',kind='symlink',target='x')],external_files={})],'archive_virtual_graph',scope='双源组合：内部链接身份与解包根包含关系。只支持公开的受控虚拟树和tar子集，不要求系统级安全归档工具、未知损坏文件或竞态防御。')
    add('N21','equivalent_sql_aggregation',[
        C('word_statistics','word_statistics',{'tables':R+'/tables'},"tables包含words(wordid,word)、senses(wordid,synsetid)、synsets(synsetid,domainid,posid)。按wordid返回统计列表 [{word_id,word,total_synsets,total_senses,distinct_domains,distinct_posids}]，词没有sense也列出0；所有引用合法。"),
        C('top_synsets','top_synsets',{'tables':R+'/tables'},"每词按sense行数最多选synset，平局取较小synsetid。返回 [{word_id,top_synsetid,top_synset_sense_count}]，按word_id，只包含至少一个sense的词。"),
        C('optimized_query','optimized_query',{'statistics':O('word_statistics'),'ranks':O('top_synsets')},"返回通用只读SQLite查询字符串。对所有合法表均应输出8列：word_id,word,total_synsets,total_senses,distinct_domains,distinct_posids,top_synsetid,top_synset_sense_count；只保留total_synsets>=2、distinct_domains>=2、total_senses>=2。按total_senses/total_synsets/distinct_domains降序，再word_id升序，LIMIT 500。不能把当前统计结果硬编码为SQL常量；评测复用该SQL于不同正常数据库。接受任意等价SQL；公开工作量预算为 SQLite VM 步数 <= 200*len(senses)+20000，原始相关子查询作为负例。",emit={'outputs/sol.sql':{'pointer':'','format':'text'}}),
        C('query_result','execute_query',{'sql':O('optimized_query'),'tables':R+'/tables'},"实际在只读SQLite表执行sql，返回 {columns:上述8列名,rows:查询结果二维列表}；不输出或比较SQLite特定格式的执行计划。")],
        [dict(tables=query_data(n)) for n in [3,7,80]],'relational_python',scope='性能为核心要求，采用公开可复现的SQLite VM预算，免除不稳定墙钟比值。预算须经参考查询和原始低效查询双向验证。')
    add('N22','git_lost_objects_cleanup',[
        C('object_scan','git_object_scan',{'bundle':R+'/bundle'},"bundle是gzip-tar的base64，解包后为本地合成Git仓库，含一个历史重写后不可达对象中的secret[...]标记。通过Git对象枚举恢复，返回 {secret:完整标记}。普通文件及正常提交说明必须保持。没有真实密钥/远程服务。"),
        C('cleaned_repo','git_clean',{'bundle':R+'/bundle','scan':O('object_scan')},"先确认已恢复标记，再删除仓库中的该标记，包括reflog和不可达对象；保留普通工作区内容与正常提交说明。返回 {bundle:清理后完整仓库tar.gz的base64,files:{普通相对路径:SHA256},messages:[git log --format=%s按新到旧]}。允许任意语义正确仓库重打包，不比tar字节。",emit={'outputs/cleaned-repo.tar.gz':{'pointer':'/bundle','format':'base64'}}),
        C('recovery_report','git_recovery_report',{'scan':O('object_scan'),'cleaned':O('cleaned_repo')},"实际读取清理后的仓库，枚举全部对象验证无secret[...]；返回 {secret:恢复标记,files:普通文件SHA256映射,messages:正常提交说明列表,remaining_secret_objects:0}。",emit={'outputs/secret.txt':{'pointer':'/secret','format':'text'}})],
        [x['request'] for x in fixtures['git']],'git_fixture_gold',scope='输入以归档承载真实本地Git仓库。恢复与清理必须在可独立解包的仓库上成立；公开检查只公开标记哈希，不泄露标记明文。')
    add('N23','sqlite_wal_recovery',[
        C('base_records','sqlite_base',{'base_b64':R+'/base_b64'},"解码base64的真实SQLite基础库，在临时目录只读查询items(id,name,value)，按id返回记录列表。"),
        C('decoded_wal','decode_wal',{'encoded_wal_b64':R+'/encoded_wal_b64','codec':R+'/codec'},"公开有限破坏模型：codec.scheme='xor-byte'，每个WAL字节与codec.key(0..255)异或。还原真实WAL，返回base64字节串。不要求猜未知密码或修复任意损坏页。"),
        C('recovered','recover_sqlite',{'base_b64':R+'/base_b64','wal_b64':O('decoded_wal'),'base':O('base_records')},"把真实基础库及还原WAL按同名.db/-wal放到临时目录，让SQLite恢复并查询。返回 {records:按id排序的全部记录,base_count:基础记录数,database:原base64库,wal:还原WAL的base64}。不能仅追加两个记录列表，WAL含旧行更新。组件封装写 outputs/recovery_snapshot.json，业务列表单独写 outputs/recovered.json，不得互相覆盖。",output_file='outputs/recovery_snapshot.json',emit={'outputs/recovered.json':{'pointer':'/records','format':'json'},'outputs/repaired/main.db':{'pointer':'/database','format':'base64'},'outputs/repaired/main.db-wal':{'pointer':'/wal','format':'base64'}})],
        [x['request'] for x in fixtures['wal']],'wal_fixture_gold',scope='对原题含糊的破坏模型做显式补充：给定单字节XOR codec，不做隐藏加密猜测。恢复出的SQLite必须实际含WAL更新和插入。')
    routes={'refs/heads/main':'site/main','refs/heads/dev':'site/dev'}
    scenarios=[dict(routes=routes,batches=[[dict(branch='main',files={'index.html':'MAIN'}),dict(branch='dev',files={'index.html':'DEV','old.txt':'drop'})],[dict(branch='dev',files={'index.html':'DEV2'})]]),dict(routes=routes,batches=[[dict(branch='main',files={'index.html':'one','x.txt':'x'})],[dict(branch='main',files={'index.html':'two'})],[dict(branch='dev',files={'index.html':'dev'})]]),dict(routes=routes,batches=[[dict(branch='dev',files={'index.html':'D'})],[dict(branch='main',files={'index.html':'M'})]])]
    add('N25','local_git_branch_deploy',[
        C('branch_routes','branch_routes',{'routes':R+'/routes'},"返回路由映射独立副本，refs/heads/main与refs/heads/dev指向互不包含的相对部署目录。无SSH/Nginx/TLS。"),
        C('deployment_hook','deployment_hook',{'routes':O('branch_routes')},"返回Python post-receive业务脚本字符串，stdin每行old new ref；一次可有多行。GIT_DIR来自环境，MEDIUM30_DEPLOY_ROOT为部署根。对路由内非删除ref，把new commit树完整部署到对应目录，清除该分支旧文件但不影响另一分支；未路由ref忽略。提供的run_deploy负责创建仓库、安装Python启动shim及真实git push，脚本只需实现业务分派。允许任意正确脚本，不比脚本文本。",emit={'outputs/post-receive.py':{'pointer':'','format':'text'}}),
        C('deployment_report','deployment_report',{'hook':O('deployment_hook'),'routes':O('branch_routes'),'batches':R+'/batches'},"调用公开runtime.run_deploy(hook,routes,batches)或等价本地Git流程。batches每批包含待提交branch和完整files快照，需真实git push触发hook。返回 {files:{部署根下相对文件路径:UTF8内容}}。只测试有效提交和本地正常push，不测失败回滚/网络。")],scenarios,'deploy_snapshots',scope='移除SSH、HTTPS及3秒墙钟门槛；保留真实本地Git多ref接收hook与两个分支的部署隔离。')
    add('N26','dual_kl_distribution',[
        C('probability_model','probability_model',{'n':R+'/n','groups':R+'/groups','targets':R+'/targets'},"返回 {n,groups,targets}。groups为三个正整数且和为n，第1组1个元素；构造分组常数概率可作为标准数值求根的低维参数化。targets={forward,backward}，本版均为10；n=150000。不要求指定算法或特定解。"),
        C('distribution','solve_distribution',{'model':O('probability_model')},"构造长度model.n的正概率向量列表，和误差<=1e-5；KL(P||U)及KL(U||P)分别与targets误差<=0.001，使用自然对数。返回概率列表，允许任意合法解。可用预装NumPy/SciPy标准求根；无需GPU或训练。",emit={'outputs/dist.npy':{'pointer':'','format':'npy'}}),
        C('distribution_report','distribution_report',{'probabilities':O('distribution'),'model':O('probability_model')},"返回 {size,mass,forward_kl,backward_kl,meets_target:bool}，必须从同一个概率向量实际重算；数值按公开容差验收而非精确字符串。")],
        [dict(n=150000,groups=[1,k,149999-k],targets=dict(forward=10.,backward=10.)) for k in [100,50,500]],'distribution_feasible',scope='保留原题双KL目标和公开容差。正概率、归一化和有限KL是数学核心；不添加额外小数精度、唯一向量或固定优化器要求。')
